function isQuestionOpen(q){return !!prerequisiteEvidence(q);}
function questionStatus(q){const f=followState()[q.id],version=q.quoteVersion||1,confirmed=f?.checkedVersion===version||f?.recorded&&f.version===version;return confirmed?uiCopy('확인함 ✓')+(pending.sources.includes(followEvidenceId(q))?uiCopy(' · 내 판단 근거로 선택'):f?.recorded&&f.version===version?uiCopy(' · 수첩에 기록'):uiCopy(' · 수첩 기록 전')):f?.recorded&&q.quoteVersion===2?uiCopy('새 답변 확인 전'):isQuestionOpen(q)?uiCopy('새로 물어볼 수 있어요 · 아직 확인 전'):uiCopy('잠김 · 먼저 ')+tr(clue(q.need).label)+uiCopy(' 단서를 기록해요');}
