function showFollowup(){const q=followupQuestions.find(q=>q.id===state.followupOpen);if(!q)return;const e=prerequisiteEvidence(q);dialog(uiCopy('단서를 보고 더 물어보기'),'<h3>'+escape(uiCopy(q.question))+uiCopy('</h3><h4>질문의 출발 단서</h4><p>')+escape(uiCopy(tr(e?.fact||'')))+'</p>'+(q.quote?speaker(q.who,uiCopy(q.quote)):uiCopy('<p class="notice">이 질문에 대한 인물의 추가 답변은 아직 없습니다.</p>'))+uiCopy('<h4>아직 모르는 점</h4><p>')+escape(uiCopy(q.unknown))+uiCopy('</p><p>답이 없다는 이유로 누가 잘못했는지 정하지 않아요.</p>'),btn(q.quote?uiCopy('답변과 남은 질문을 수첩에 기록'):uiCopy('아직 답이 없는 질문으로 기록'),'record-follow:'+q.id)+btn(uiCopy('다른 질문 보기'),'follow-list')+btn(uiCopy('내 판단 다시 보기'),'decision'));}
renderPanel=function(){if(panel==='followup')return showFollowup();if(panel==='follow-list')return dialog(uiCopy('더 물어볼 질문'),questionList());followPanel();};
resultHTML=function(){return followResult()+uiCopy('<h2>후속 질문에서 확인한 내용</h2>')+followupQuestions.filter(q=>followState()[q.id]?.recorded&&followState()[q.id].version===(q.quoteVersion||1)).map(q=>'<section><h3>'+escape(uiCopy(q.question))+'</h3><p>'+escape(uiCopy(q.quote)||uiCopy('추가 답변 미확인'))+uiCopy('</p><p>아직 모르는 점: ')+escape(uiCopy(q.unknown))+'</p></section>').join('');};
act=function(action){const [a,id]=action.split(':');if(a==='ask-follow'){const q=followupQuestions.find(q=>q.id===id);if(!q||!isQuestionOpen(q))return;if(panel)closePanel();followState()[id]??={};followState()[id].asked=true;state.followupOpen=id;openPanel('followup');persist();return;}if(a==='record-follow'){const q=followupQuestions.find(q=>q.id===id),f=followState()[id];if(!q||!f?.asked||panel!=='followup'||state.followupOpen!==id)return;if(!f.recorded||f.version!==(q.quoteVersion||1)){const n=ensureNote();n.evidence.push({source:followEvidenceId(q),fact:[q.quote||uiCopy('이 질문의 답은 아직 확인되지 않았어요: ')+q.question,uiEnglish(q.quote||q.question)],limit:[q.unknown,uiEnglish(q.unknown)],question:q.question,kind:q.quote?'testimony':'unanswered-question',at:new Date().toISOString()});f.recorded=true;f.version=q.quoteVersion||1;}persist();renderPanel();return;}if(a==='follow-list'){if(panel)closePanel();state.followupOpen=null;openPanel('follow-list');persist();return;}return followAct(action);};
const followClose=closePanel;closePanel=function(){state.followupOpen=null;followClose();};
