function judgmentRecordHTML(j){if(!j)return '<p>'+L('아직 판단 기록이 없어요.','No judgment recorded yet.')+'</p>';const separated=typeof j.judgment==='string'&&j.judgment.trim();return '<dl class="judgmentRecord"><dt>'+L('선택한 근거','Selected evidence')+'</dt><dd>'+j.sources.map(id=>escape(tr(clue(id)?.label||id))).join(' · ')+'</dd><dt>'+L('판단','Judgment')+'</dt><dd>'+escape(j.deferred?L('아직 판단하기 어려움 · 판단 유보','Not ready to decide')+(separated?' — '+j.judgment:''):separated?j.judgment:L('별도 판단 문장 없이 생각과 이유를 함께 남겼어요.','The thought and reason were written together, without a separate judgment.'))+'</dd><dt>'+ (separated?L('이유','Reason'):L('당시 쓴 생각과 이유 (원문)','Thought and reason as originally written'))+'</dt><dd class="studentOriginal">'+escape(j.reason)+'</dd><dt>'+L('남은 질문','Remaining question')+'</dt><dd>'+escape(j.unknown||L('아직 적지 않음','Not written yet'))+'</dd></dl>';}
