 const heading=state.round===1?L('1단계 사건에서 → 2단계 단서로','From the case in Step 1 → evidence in Step 2'):state.round===2?L('2단계 근거에서 → 3단계 판단으로','From evidence in Step 2 → a judgment in Step 3'):L('3단계 판단에서 → 4단계 해결로','From the judgment in Step 3 → a solution in Step 4');
