let lastEndingSurface='';
renderEnd=function(){const e=endState(),l=activeLetter();
 // Saved older ending stages keep their letter and move to the unified recipient scene.
 if(['sent','reactions','actions'].includes(e.stage)&&l)e.stage='scene';
 if(e.stage==='letter'&&!e.draft)e.draft={to:'',body:'',evidence:[],signature:endSignature()};
 if(['scene','record'].includes(e.stage)&&!l)e.stage='review';
 let html=endingHeader(e.stage);
 if(e.stage==='review'){
  html+=uiCopy('<section class="caseIntro"><h1 id="ending-title" tabindex="-1">사건 조사 결과</h1><p>내가 확인한 근거로 설명과 행동을 부탁하는 편지를 보내요.</p>')+btn(uiCopy('편지 쓰기'),'letter-open','primary','id="letter-open-button"')+uiCopy('<details><summary>내 조사와 판단 다시 보기</summary>')+briefInvestigation()+'</details>';
  if(l&&l.signature!==endSignature())html+=uiCopy('<p>판단이나 계획이 바뀌었어요. 이전 편지는 보존하고 새 편지를 쓸 수 있어요.</p>');
  html+='</section>';
 }
 if(e.stage==='letter'){
  const d=e.draft;
  html+=uiCopy('<section class="letterTool" role="region" aria-labelledby="ending-title"><header class="letterToolHead"><span aria-hidden="true">✉</span><h1 id="ending-title" tabindex="-1">윤리시티에서 보내는 편지</h1></header><div class="letterToolBody">')+'<details class="letterContext"><summary>'+L('이 편지로 이어지는 내 판단과 행동','My judgment and actions behind this letter')+'</summary>'+judgmentRecordHTML(latestJudgment(3)||latestJudgment(2))+'<p>'+state.plans.map(i=>escape(uiCopy(END_ACTIONS[i].title))).join(' · ')+'</p></details>'+'<fieldset class="letterRecipient"><legend>'+L('받는 사람','To')+'</legend><p class="notice">'+L('한 사람에게 편지를 보내도 모든 책임이 그 사람에게 있다는 뜻은 아니에요.','Sending a letter to one person does not mean that person holds all the responsibility.')+'</p><div class="recipientChoices">'+END_PEOPLE.map(id=>btn(escape(L(...RECIPIENT_ROLES[id])),'letter-to:'+id,d.to===id?'primary':'','aria-pressed="'+(d.to===id)+'"')).join('')+'</div></fieldset>'+uiCopy('<label for="letter-body">무엇을 설명하거나 함께 해 달라고 부탁할까요?</label><textarea id="letter-body" rows="3" maxlength="500" placeholder="확인한 근거와 부탁을 짧게 적어 주세요.">')+escape(d.body)+uiCopy('</textarea><section class="letterEvidence" id="letter-evidence-panel"><h3>편지의 근거 고르기 (필수)</h3><fieldset><legend>실제로 조사한 자료</legend>')+sourcesNow().map(ev=>'<label class="letterChoice"><input type="checkbox" class="letter-evidence" value="'+ev.source+'" '+(d.evidence.includes(ev.source)?'checked':'')+'>'+escape(tr(clue(ev.source).label))+'</label>').join('')+uiCopy('</fieldset></section><p id="letter-error" role="status" aria-live="polite"></p><small>게임 속 편지예요. 실명·주소는 쓰지 않아요.</small></div><footer class="letterToolActions">')+btn(uiCopy('발송'),'letter-send','primary','id="letter-send-button"')+btn(uiCopy('돌아가기'),'letter-back')+'</footer></section>';
 }
 if(e.stage==='scene'&&l){
  const who=RECIPIENT_ENDINGS[l.to];
  html+='<section class="recipientEnding" data-recipient="'+l.to+'"><h1 id="ending-title" tabindex="-1">'+escape(uiCopy(who.title))+uiCopy('</h1><figure class="endingScene"><canvas id="ending-world" width="960" height="640" aria-label="편지를 받은 인물과 후속 조치를 살펴보는 교실"></canvas><figcaption>')+speaker(l.to,uiCopy(who.line))+uiCopy('</figcaption></figure><div class="chosenActions"><h2>우리가 부탁한 회복·예방 행동</h2>')+l.plans.map(i=>'<p>'+escape(uiCopy(END_ACTIONS[i].title))+' — '+escape(uiCopy(END_ACTIONS[i].line))+'</p>').join('')+uiCopy('</div><p class="endingLimit">편지 내용의 자동 해석이나 실제 조치 완료가 아닌 게임 속 장면이에요.</p>')+btn(uiCopy('조사 마치기'),'ending-record','primary','id="case-finish-button"')+'</section>';
 }
 if(e.stage==='record'){
  html+=uiCopy('<section class="caseSolved"><span class="caseSeal" aria-hidden="true">✓</span><h1 id="ending-title" tabindex="-1">Case solved</h1><h2>윤리시티 사건 조사를 마쳤어요</h2><p>근거를 살피고, 책임과 필요한 행동을 생각했어요. 실제 회복과 약속의 이행은 앞으로도 확인해야 해요.</p><details><summary>문제 해결 조사 기록 다시 보기</summary>')+resultHTML()+e.letters.map(x=>'<section class="letterArchive">'+letterDisplay(x)+uiCopy('<h3>발송 당시 판단</h3>')+x.judgments.map(j=>'<p>'+escape(j.reason)+uiCopy(' / 더 확인할 것: ')+escape(j.unknown||uiCopy('미작성'))+'</p>').join('')+uiCopy('<h3>선택한 회복·예방 행동</h3>')+x.plans.map(i=>'<p>'+escape(uiCopy(END_ACTIONS[i].title))+'</p>').join('')+btn(uiCopy('이 수신자의 장면 다시 보기'),'letter-replay:'+x.id)+'</section>').join('')+'</details></section>';
 }
 $('app').innerHTML=html+endNavigation();
 if(e.stage==='letter'){$('letter-body').value=e.draft.body;for(const el of document.querySelectorAll('#letter-body, .letter-evidence'))el.oninput=el.onchange=()=>{readLetterDraft();persist();};}
 if(e.stage==='scene'&&l){const i=l.plans[0];if(Number.isInteger(i)&&END_ACTIONS[i])drawEndingAction($('ending-world'),i);else drawWorld($('ending-world'),true);}
 const surface=e.stage+':'+(e.active||'');if(surface!==lastEndingSurface){$('ending-title')?.focus();$('app').scrollIntoView?.({block:'start',behavior:'instant'});lastEndingSurface=surface;}
};
function sendGameLetter(){const e=endState();if(e.stage!=='letter'||!e.draft)return;readLetterDraft();const d=e.draft,available=sourcesNow();if(!END_PEOPLE.includes(d.to)){$('letter-error').textContent=L('받는 사람을 먼저 골라요.','Choose a recipient first.');return;}if(!d.body.trim()||!d.evidence.length||d.evidence.some(id=>!available.some(x=>x.source===id))){$('letter-error').textContent=uiCopy('받는 사람, 실제로 확인한 근거, 짧은 편지 내용을 남겨 주세요.');if(!d.evidence.length&&$('letter-evidence-panel'))$('letter-evidence-panel').open=true;$('letter-error').scrollIntoView?.({block:'nearest'});return;}if(d.signature!==endSignature()){$('letter-error').textContent=uiCopy('판단이나 계획이 바뀌었어요. 조사 결과로 돌아가 현재 판단으로 새 편지를 시작해 주세요.');return;}const l={id:e.letters.length+1,to:d.to,body:d.body.trim(),evidence:JSON.parse(JSON.stringify(available.filter(x=>d.evidence.includes(x.source)))),judgments:JSON.parse(JSON.stringify(judgments)),plans:[...state.plans],planBasis:JSON.parse(JSON.stringify(state.planBasis||{})),signature:d.signature,at:new Date().toISOString(),delivery:'fictional-game-only'};l.reactions=reactionList(l);d.sent=true;e.letters.push(l);e.active=l.id;e.stage='scene';e.actionIndex=0;persist();render();}
const endingAct=act;act=function(action){const [a,id]=action.split(':');const e=endState();if(a==='letter-open'){if(!judgments.length||!state.plans.length)return;if(panel)closePanel();state.screen='end';e.stage='letter';if(!e.draft||e.draft.signature!==endSignature()||e.draft.sent)e.draft={to:'',body:'',evidence:[],signature:endSignature()};render();persist();return;}if(a==='letter-to'){if(e.stage!=='letter'||!e.draft||!END_PEOPLE.includes(id))return;readLetterDraft();e.draft.to=id;render();persist();return;}if(a==='letter-send'){sendGameLetter();if(e.stage==='scene'){e.draft.sent=true;persist();}return;}if(a==='letter-back'){readLetterDraft();e.stage='review';render();return;}if(a==='letter-replay'){const l=e.letters.find(l=>l.id===Number(id));if(!l)return;e.active=l.id;e.stage='scene';render();return;}if(['ending-reactions','ending-actions','ending-record','ending-next-action'].includes(a)){if(!activeLetter())return;e.stage=(a==='ending-record'||a==='ending-next-action')?'record':'scene';render();return;}if(a==='revision-revisit')readLetterDraft();if(a==='revision-new'){const before=state;const result=endingAct(action);if(state.screen==='start'&&state===before){delete state.ending;persist();}return result;}if(a==='save-exit')readLetterDraft();return endingAct(action);};
const endingStyle=document.createElement('style');endingStyle.textContent='.letterLayout{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(0,1fr);gap:32px}.letterLayout aside{border-left:1px solid var(--line);padding-left:24px}.letterChoice{display:block;padding:8px 0}.letterChoice small{display:block;margin-left:28px}.letterText{white-space:pre-wrap;overflow-wrap:anywhere;background:var(--paper);padding:24px;border:2px solid #a99570;margin:16px 0}.letterArchive{border-top:2px solid var(--line);margin-top:32px;padding-top:24px}.deliveryScene{display:flex;align-items:center;gap:24px;background:var(--paper);padding:24px}.paperLetter{border:3px solid #a99570;padding:20px 40px;animation:letter-arrive .5s ease-out}.endingScene{margin:16px 0;position:relative;max-width:800px;background:var(--paper);border:3px solid #748e76}.endingScene canvas{display:block;width:100%;image-rendering:pixelated}.actionFocus{position:absolute;left:15%;right:15%;top:68%;display:flex;align-items:center;justify-content:center;gap:20px;background:#fffdf3ed;border:3px solid #748e76;padding:16px}.actionFocus .portrait{width:80px;height:96px;object-fit:contain;image-rendering:pixelated}.sceneProp{padding:16px;border:3px solid #a99570;background:#e7ead4;animation:letter-arrive .4s ease-out}.prop0{border-style:dashed;background:#e0bc80}.prop2{border-color:#ba7833}.endingScene figcaption{padding:16px}.letterLayout textarea{width:100%}@keyframes letter-arrive{from{transform:translateX(-20px);opacity:.2}to{transform:translateX(0);opacity:1}}@media(prefers-reduced-motion:reduce){.paperLetter,.sceneProp{animation:none}}@media(max-width:760px){.letterLayout{grid-template-columns:1fr}.letterLayout aside{border-left:0;padding-left:0}.actionFocus{left:4%;right:4%;top:62%;gap:8px;padding:8px}.actionFocus .portrait{width:48px;height:64px}.sceneProp{font-size:14px;padding:8px}}';document.head.appendChild(endingStyle);
