function followRecorded(q){const f=followState()[q.id];return !!f?.recorded&&f.version===(q.quoteVersion||1);}
function relatedQuestions(source=state.target){const root=source?.startsWith('follow-')?followupQuestions.find(q=>followEvidenceId(q)===source||'follow-'+q.id===source)?.who:source;return followupQuestions.filter(q=>isQuestionOpen(q)&&(q.need===root||q.who===root)).sort((a,b)=>Number(followRecorded(a))-Number(followRecorded(b)));}
function followMenu(){
 const ui=state.followupUI??={who:null,page:0};const available=followupQuestions.filter(isQuestionOpen);
 if(!END_PEOPLE.includes(ui.who)){ui.who=(relatedQuestions()[0]||available[0])?.who||'gayoung';ui.page=0;}
 const group=available.filter(q=>q.who===ui.who).sort((a,b)=>Number(followRecorded(a))-Number(followRecorded(b)));const pages=Math.max(1,Math.ceil(group.length/2));ui.page=Math.min(ui.page,pages-1);const shown=group.slice(ui.page*2,ui.page*2+2);
 const locked=followupQuestions.filter(q=>!isQuestionOpen(q));
 return uiCopy('<p>확인한 단서에서 이어지는 질문만 골라요.</p><label for="follow-person">누구에게 물어볼까요?</label><select id="follow-person">')+END_PEOPLE.map(id=>'<option value="'+id+'" '+(ui.who===id?'selected':'')+'>'+escape(tr(clue(id).label))+'</option>').join('')+'</select><div class="followChoices">'+(shown.length?shown.map((q,i)=>'<div><small>'+escape(questionStatus(q))+'</small>'+btn(escape(uiCopy(q.question)),'ask-follow:'+q.id,i===0?'primary':'')+'</div>').join(''):uiCopy('<p>이 인물에게 새로 물어보려면 관련 단서를 먼저 살펴보세요.</p>'))+'</div>'+(pages>1?uiCopy('<p>질문 ')+(ui.page+1)+' / '+pages+'</p>'+btn(uiCopy('다음 질문 묶음'),'follow-page'):'')+(locked.length?uiCopy('<details><summary>더 확인할 단서</summary><ul>')+locked.map(q=>'<li>'+escape(tr(clue(q.who).label))+' · '+escape(uiCopy(q.question))+' — '+escape(tr(clue(q.need).label))+uiCopy(' 확인 후 열려요.</li>')).join('')+'</ul></details>':'');
}
questionList=function(){return followMenu();};
showFollowup=function(){const q=followupQuestions.find(q=>q.id===state.followupOpen);if(!q)return;const e=prerequisiteEvidence(q);dialog(uiCopy('단서를 보고 물어보기'),'<h3>'+escape(uiCopy(q.question))+'</h3>'+speaker(q.who,uiCopy(q.quote)||uiCopy('아직 추가 답변이 없어요.'))+uiCopy('<p><strong>아직 단정할 수 없는 점</strong><br>')+escape(uiCopy(q.unknown))+uiCopy('</p><details><summary>질문의 출발 단서 보기</summary><p>')+escape(uiCopy(tr(e?.fact||'')))+'</p></details>',btn(followRecorded(q)?uiCopy('조사로 돌아가기'):uiCopy('확인한 내용을 기록하기'),followRecorded(q)?'follow-return':'record-follow:'+q.id,'primary')+btn(uiCopy('다른 질문'),'follow-list'));if(q.quote){const f=followState()[q.id]??={};f.checkedVersion=q.quoteVersion||1;persist();}};
