const compactAct=act;
act=function(action){if(action.startsWith('perspective:')){if(panel!=='question'||!$('memo'))return;const id=action.split(':')[1];ensureNote().perspective=id;if(id!=='free'){const p=QUESTION_PERSPECTIVES.find(p=>p.id===id);if(p)$('memo').value=L(...p.text);}for(const chip of document.querySelectorAll('.perspectiveChip')){const isThis=chip.dataset.action==='perspective:'+id;chip.setAttribute('aria-pressed',String(isThis));let mark=chip.querySelector('.perspectiveSelectedMark');if(isThis){if(!mark){mark=document.createElement('small');mark.className='perspectiveSelectedMark';chip.appendChild(mark);}mark.textContent=L('선택함 ✓','Selected ✓');}else if(mark)mark.remove();}$('memo').focus();persist();return;}if(action==='solve-prepare'){if(state.screen!=='play'||state.round!==2)return;return compactAct('decision');}if(action==='compact-source'){const id=$('investigation-source').value;if(originalClueIds.includes(id))return compactAct('source:'+id);return;}if(action.startsWith('judgment-kind:')){if(panel!=='decision')return;draftRead();pending.kind=action.split(':')[1];if($('judgment-kind'))$('judgment-kind').value=pending.kind;persist();renderPanel();return;}if(action.startsWith('commit-step:')){if(Number(action.split(':')[1])!==state.round||panel!=='decision')return;const kind=$('judgment-kind')?.value;if(kind!=='reasoned'&&kind!=='deferred'){if($('decision-error'))$('decision-error').textContent=nextActionHint();return;}return compactAct(kind==='deferred'?'defer-judgment':'commit-judgment');}if(action==='compact-commit'){const kind=$('judgment-kind')?.value;if(kind!=='reasoned'&&kind!=='deferred'){if($('decision-error'))$('decision-error').textContent=nextActionHint();return;}return compactAct(kind==='deferred'?'defer-judgment':'commit-judgment');}if(action==='book')return openPanel('book');if(action==='follow-related'){const e=note()?.evidence.at(-1),q=relatedQuestions(e?.source).find(q=>!followRecorded(q));state.followupUI={who:q?.who||'gayoung',page:0};return compactAct('follow-list');}if(action==='follow-page'){state.followupUI.page++;renderPanel();return;}if(action==='follow-return'){if(panel)closePanel();state.phase='review';render();return openPanel('review');}if(action.startsWith('record-follow:')){const id=action.split(':')[1];const q=followupQuestions.find(q=>q.id===id);const eligible=q&&panel==='followup'&&state.followupOpen===id&&followState()[id]?.asked;const result=compactAct(action);if(eligible&&followRecorded(q)){closePanel();state.phase='review';render();openPanel('review');}return result;}return compactAct(action);};
