// TEAM COMMON INTEGRATION
// Team integration adapter: no student-authored content leaves this game.
(function () {
  'use strict';
  const base = '../shared/ethicity-elementary-common-v1';
  const api = window.EthicityAssets;
  const manifest = window.ETHICITY_COMMON_MANIFEST;
  const assets = api && manifest ? new api.CommonAssets(manifest, base) : null;
  let iconLoaded = false, lastProgress = null, completedSent = false;
  function send(message) {
    // The team portal and game are served from the same origin. No wildcard recipient.
    const origin = window.location?.origin;
    if (window.parent && window.parent !== window && origin && origin !== 'null') {
      window.parent.postMessage(message, origin);
    }
  }
  function sync() {
    const ending = state.ending;
    const hasLetter = !!ending?.letters?.length;
    if (hasLetter && ending.stage === 'record') state.integrationCompleted = true;
    const rounds = new Set(judgments.map(j => j.round).filter(n => Number.isInteger(n) && n >= 0 && n < 4)).size;
    const current = Math.min(6, rounds + (hasLetter ? 1 : 0) + (hasLetter && state.integrationCompleted ? 1 : 0));
    if (!rounds && !hasLetter) completedSent = false;
    if (current !== lastProgress) {
      send({type:'ethicity:progress', gameId:'accountability', current, total:6});
      lastProgress = current;
    }
    if (current === 6 && !completedSent) {
      send({type:'ethicity:complete', gameId:'accountability', result:{completed:true}});
      completedSent = true;
    }
  }
  function theme() {
    document.body?.classList?.add('ee-theme', 'game-accountability');
    for (const button of document.querySelectorAll('button')) {
      button.classList.add('ee-button');
      button.classList.toggle('secondary', !button.classList.contains('primary'));
    }
    for (const panel of document.querySelectorAll('.flowRail, #modal')) panel.classList.add('ee-panel');
    if (iconLoaded) {
      const brand = document.getElementById('brand');
      if (brand?.insertBefore && !document.getElementById('common-investigation-icon')) {
        const canvas = document.createElement('canvas');
        canvas.id = 'common-investigation-icon'; canvas.width = canvas.height = 32;
        canvas.setAttribute('aria-hidden', 'true'); canvas.className = 'ee-icon';
        assets.drawIcon(canvas.getContext('2d'), 'inspect', 0, 0, 32);
        brand.insertBefore(canvas, brand.firstChild);
      }
    }
  }
  const previousRender = render, previousPanel = renderPanel, previousAct = act;
  render = function () { const result = previousRender.apply(this, arguments); theme(); sync(); return result; };
  renderPanel = function () { const result = previousPanel.apply(this, arguments); theme(); return result; };
  act = function () { const result = previousAct.apply(this, arguments); theme(); sync(); persist(); return result; };
  if (assets) {
    const icon = new Image();
    icon.onload = () => { assets.images.set(manifest.icons.image, icon); iconLoaded = true; theme(); };
    // Load only the icon actually used; the runtime's full load() also fetches every map/character.
    icon.onerror = () => { iconLoaded = false; };
    icon.src = window.ACCOUNTABILITY_COMMON_ICON || assets.path(manifest.icons.image);
  }
  theme();
  send({type:'ethicity:ready', gameId:'accountability'});
  sync();
})();

