// Auto-walk must end inside inspect range: nearestObject() accepts < 31px and the BFS grid can stop up to 9px short of its goal.
function walkToTarget(){
  const o=WORLD.objects.find(o=>o.id===state.target);if(!o)return;
  if(nearestObject()?.id===o.id)return inspectNearby();
  const cx=o.x,cy=o.y+o.h/2,R=16,REACH=28;
  const goals=[{x:cx,y:cy+R},{x:cx-R,y:cy+10},{x:cx+R,y:cy+10},{x:cx,y:cy-R},{x:cx-R,y:cy-10},{x:cx+R,y:cy-10}];
  const reach=path=>{const e=path[path.length-1];return Math.hypot(e.x-cx,e.y-cy);};
  const routes=goals.map(goal=>({goal,path:walkPath(explorer,goal)})).filter(r=>r.path.length)
    .sort((a,b)=>(reach(a.path)>=REACH)-(reach(b.path)>=REACH)||a.path.length-b.path.length);
  const best=routes[0];
  if(!best){explorer.route=[];$('world')?.focus();return;}
  const end=best.path[best.path.length-1];
  if(reach(best.path)>=REACH&&clearSegment(end,best.goal))best.path.push({x:best.goal.x,y:best.goal.y});
  explorer.route=best.path;$('world')?.focus();
}

