   for(const {i}of choices){const el=$('plan-basis-'+i);if(el)el.onchange=()=>{state.planBasis??={};const id=el.value;if(id&&sourcesNow().some(e=>e.source===id))state.planBasis[i]=id;else delete state.planBasis[i];persist();};}return;
