 const oldActivity=renderActivity;renderActivity=function(){if(['minho','gayoung','teacher','company','robot'].includes(state.target)&&state.easyDefaultTarget!==state.target){easy=true;state.easyDefaultTarget=state.target;}return oldActivity.apply(this,arguments);};
